/// Pure relation lookup; unknown state, event or guard values refuse.
pub fn transition(from: &str, event: &str, guard: &str) -> Option<(&'static str, Option<&'static str>)> {
    // Only a listed complete tuple has a continuing destination.
    ALLOWED.iter().find(|r| r.0 == from && r.1 == event && r.2 == guard).map(|r| (r.3,r.4))
}
